"<strong>+37%</strong><span>Retention</span>": "<strong>+37%</strong><span>Retención</span>",
"<strong>−20.5%</strong><span>Payment-related complaints</span>": "<strong>−20,5%</strong><span>Quejas relacionadas con pagos</span>",
"<strong>+25%</strong><span>Engagement</span>": "<strong>+25%</strong><span>Engagement</span>",
"<strong>−15%</strong><span>Customers missing payments</span>": "<strong>−15%</strong><span>Clientes con pagos atrasados</span>",
"<strong>+10%</strong><span>Average Flex spending</span>": "<strong>+10%</strong><span>Gasto medio en Flex</span>",
